    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base: prefer small post‑residual, but also penalize bins that are too under‑filled before placement
    let occupancy_before = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let mut score = post_residual as f64 * (1.0 + (1.0 - occupancy_before));

    // 2‑step lookahead with non‑linear scaling
    if next_item_size > 0 {
        let can_fit_next = post_residual >= next_item_size;
        let delta = if can_fit_next {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64
        };
        let factor = if can_fit_next { 0.4 } else { 0.6 };
        score += delta * factor;
    }

    // Penalize deviation from mean residual (quadratic penalty)
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * diff * 0.05;

    // Reward if this is the only bin that can accept the item
    if fitting_bins_count == 1 {
        score -= 1200.0;
    }

    // Special handling for a brand‑new empty bin
    if bin_residual == bin_capacity {
        // Open‑bin penalty grows with the number of bins already open
        if open_bins_count > 20 {
            score += 120.0;
        } else if open_bins_count > 10 {
            score += 80.0;
        } else if open_bins_count > 5 {
            score += 40.0;
        }

        // Reward if residual after placing is close to the mean
        if diff < 8.0 {
            score -= 25.0;
        }

        // Additional reward if the item is large relative to capacity
        if (item_size as f64) / (bin_capacity as f64) > 0.8 {
            score -= 15.0;
        }
    }

    // Progress‑based weighting: early stages penalise large residuals more heavily
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.3 {
        score += post_residual as f64 * 0.15;
    } else if progress > 0.8 {
        score -= post_residual as f64 * 0.1;
    } else {
        score -= post_residual as f64 * 0.05;
    }

    // Prefer bins where the post‑residual is close to the item size (tight fit)
    let tightness = (post_residual as i32 - item_size as i32).abs() as f64;
    score += tightness * 0.02;

    // Penalise bins that leave too much empty space relative to capacity
    let space_ratio = post_residual as f64 / bin_capacity as f64;
    if space_ratio > 0.5 {
        score += space_ratio * 30.0;
    }

    score
