        score -= 4.0;
    }

    // ------------------------------------------------------------------
    // 9. New‑bin decision – penalise opening unless it is a perfect fit
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity {
        if item_size == bin_capacity {
            score -= 2.5;
        } else {
            score += 7.5;
        }
        // Slightly favour new bins later in the stream
