pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // use item_size for a lightweight fit bonus
    let item_ratio = item_size as f64 / bin_capacity as f64;
    let mut score = post_residual as f64 - (1.0 - item_ratio) * 2.0;

    // residual vs mean: penalise large gaps, reward small gaps
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.4;
    } else {
        score -= (-diff) * 0.1;
    }

    // dead‑space penalty for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        score += 8.0 * (gap as f64);
    }

    // pressure from many open bins – prefer using existing bins
    score += (open_bins_count as f64) * 0.25;

    // bonus if this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // new‑bin candidate penalty – lowered if many bins are already open or many fits exist
    if bin_residual == bin_capacity {
        let mut new_penalty = 18.0;
        if open_bins_count > 4 {
            new_penalty -= 4.0;
        }
        if fitting_bins_count > 3 {
            new_penalty -= 2.0;
        }
        score += new_penalty;
    }

    // lookahead: if the next item is more than half the bin capacity, favour using this bin
    if next_item_size > 0 && next_item_size > bin_residual / 2 {
        score -= 3.0;
    }

    // gradually reduce penalties as the stream progresses
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score *= 1.0 - 0.15 * progress;
    }

    score
